css:
:root{--paper:#FBFAF7;--surface:#FFFFFF;--rule:#E3DED3;--rule-strong:#1A1512;--ink:#1A1512;--ink-2:#5E574C;--ink-3:#938B7C;
--band:#1A1512;--band-ink:#F5F1E8;--band-ink-2:#A79E8E;--key:#B03A28;--chair:#E0AE2E;--chair-bg:#FBF1D5;--chair-mk:#9A7716;
--sans:"PingFang SC","Hiragino Sans GB","Microsoft YaHei",system-ui,-apple-system,sans-serif;--song:"Songti SC","STSong","Songti TC","SimSun",serif;--mono:ui-monospace,"SF Mono",Menlo,Consolas,monospace;color-scheme:light}
*{box-sizing:border-box;margin:0;padding:0}html{scroll-behavior:smooth}
body{background:var(--paper);color:var(--ink);font-family:var(--sans);font-size:15px;line-height:1.7;-webkit-font-smoothing:antialiased;overflow-x:hidden}
.wrap{max-width:1140px;margin:0 auto;padding:0 32px}
.band{background:var(--band);color:var(--band-ink);padding:36px 0 28px}
.band .kicker{font-family:var(--mono);font-size:12px;letter-spacing:.08em;color:var(--band-ink-2)}
.band h1{font-family:var(--song);font-size:32px;font-weight:600;line-height:1.3;margin:8px 0 6px;color:var(--band-ink)}
.band p{font-size:14px;color:var(--band-ink-2);max-width:60em}
.topnav{position:sticky;top:0;z-index:20;background:rgba(251,250,247,.94);backdrop-filter:blur(8px);border-bottom:1px solid var(--rule)}
.topnav .wrap{display:flex;gap:4px;overflow-x:auto;padding:8px 32px;white-space:nowrap}
.topnav a{text-decoration:none;font-family:var(--mono);font-size:12.5px;color:var(--ink-2);padding:4px 10px;border-radius:999px}.topnav a:hover{background:#F5F2EB;color:var(--ink)}
.legend{display:flex;flex-wrap:wrap;gap:18px;margin:22px 0 4px;font-size:13px;color:var(--ink-2)}
.legend i{display:inline-block;width:22px;height:0;border-top:2.4px solid;vertical-align:middle;margin-right:6px}
figure{margin:52px 0 0}
.fh{display:grid;grid-template-columns:72px 1fr;gap:0 14px;border-top:2px solid var(--rule-strong);padding-top:14px;align-items:start}
.fh .ch{font-family:var(--song);font-size:52px;line-height:.85;font-weight:600;color:var(--key)}
.fh h2{font-size:22px;font-weight:600;line-height:1.3;padding-top:2px}
.fh figcaption{grid-column:2;color:var(--ink-2);font-size:14px;margin-top:4px;max-width:60em}
.fig{margin-top:16px;padding:18px 18px 12px;background:var(--surface);border:1px solid var(--rule);border-radius:10px;overflow-x:auto}
.fig svg{display:block;width:100%;height:auto;max-width:100%;font-family:var(--sans)}
.slot{margin-top:10px;display:inline-block;font-family:var(--mono);font-size:12px;color:var(--chair-mk);background:var(--chair-bg);border-left:3px solid var(--chair);padding:4px 10px;border-radius:0 4px 4px 0}
footer{padding:44px 0 56px;color:var(--ink-3);font-size:13px}
@media(max-width:900px){.wrap{padding:0 18px}.fh{grid-template-columns:1fr}.fh .ch{font-size:36px}.fh h2{font-size:19px}}
.vlbl{font-family:var(--mono);font-size:11.5px;letter-spacing:.04em;color:var(--ink-3);margin:0 0 8px}
.fig+.fig{margin-top:12px}
